// Maps the engine's stable error kinds (and the refusal / failure / problem kinds they
// carry) to translated text. Exhaustive on purpose: a new kind in the Rust enums,
// regenerated by `make types`, fails the type check here until it is translated.
import type {
  Compat,
  ErrorKind,
  LinkRefusal,
  LoginFailure,
  ProblemKind,
  ScanProblem
} from '@cloudit/api-types';
import { t, type MessageKey } from '@cloudit/ui/i18n';
import { CommandError } from './api';

const KIND_KEYS: Record<ErrorKind, MessageKey> = {
  network: 'desktop.error.network',
  unauthorized: 'desktop.error.unauthorized',
  account_blocked: 'desktop.error.account_blocked',
  forbidden: 'desktop.error.forbidden',
  not_found: 'desktop.error.not_found',
  quota_exceeded: 'desktop.error.quota_exceeded',
  conflict: 'desktop.error.conflict',
  rate_limited: 'desktop.error.rate_limited',
  server: 'desktop.error.server',
  protocol: 'desktop.error.protocol',
  scan_problems: 'desktop.error.scan_problems',
  local_changed: 'desktop.error.local_changed',
  io: 'desktop.error.io',
  disk_full: 'desktop.error.disk_full',
  cancelled: 'desktop.error.cancelled',
  not_signed_in: 'desktop.error.not_signed_in',
  not_linked: 'desktop.error.not_linked',
  paused: 'desktop.error.paused',
  link_refused: 'desktop.error.link_refused',
  login_failed: 'desktop.error.login_failed',
  token_store: 'desktop.error.token_store',
  state: 'desktop.error.state',
  invalid_input: 'desktop.error.invalid_input',
  app_outdated: 'desktop.error.app_outdated',
  server_outdated: 'desktop.error.server_outdated'
};

const REFUSAL_KEYS: Record<LinkRefusal, MessageKey> = {
  not_a_directory: 'desktop.refusal.not_a_directory',
  not_utf8: 'desktop.refusal.not_utf8',
  already_linked: 'desktop.refusal.already_linked',
  nested: 'desktop.refusal.nested',
  data_dir: 'desktop.refusal.data_dir',
  folder_already_linked: 'desktop.refusal.folder_already_linked'
};

const LOGIN_FAILURE_KEYS: Record<LoginFailure, MessageKey> = {
  denied: 'desktop.login_failure.denied',
  timed_out: 'desktop.login_failure.timed_out',
  bad_callback: 'desktop.login_failure.bad_callback'
};

const PROBLEM_KEYS: Record<ProblemKind, MessageKey> = {
  unreadable: 'desktop.problem.unreadable',
  invalid_name: 'desktop.problem.invalid_name',
  name_collision: 'desktop.problem.name_collision',
  not_utf8: 'desktop.problem.not_utf8'
};

/** The i18n key of an error kind. */
export function kindKey(kind: ErrorKind): MessageKey {
  return KIND_KEYS[kind];
}

/** Translated text for a failed command, using its details when they say more. */
export function commandErrorText(error: CommandError): string {
  const details = error.details;
  if (details?.type === 'link_refused') return t(REFUSAL_KEYS[details.reason]);
  if (details?.type === 'login_failed') return t(LOGIN_FAILURE_KEYS[details.reason]);
  if (details?.type === 'api') {
    if (details.code === 'name_taken') return t('desktop.error.name_taken');
    if (details.code === 'validation_failed') return t('desktop.error.validation');
  }
  if (details?.type === 'compat') {
    const text = compatText(details.compat);
    if (text) return text;
  }
  return t(KIND_KEYS[error.kind]);
}

/** What an incompatible server means for the user (`null`: compatible). */
export function compatText(compat: Compat): string | null {
  switch (compat.status) {
    case 'ok':
      return null;
    case 'app_outdated':
      return t('desktop.compat.app_outdated', { min: compat.min_client_version });
    case 'server_outdated':
      return t('desktop.compat.server_outdated', { version: compat.server_version });
  }
}

/** Translated text for anything thrown. */
export function errorText(error: unknown): string {
  return error instanceof CommandError ? commandErrorText(error) : t(KIND_KEYS.state);
}

/** Whether the error means "sign in again". */
export function needsSignIn(error: unknown): boolean {
  return error instanceof CommandError && error.kind === 'unauthorized';
}

export function problemText(problem: ScanProblem): string {
  return t(PROBLEM_KEYS[problem.kind]);
}
